//! A small software canvas for tapes: 0x00RRGGBB pixels in a RAM buffer (draw here, then `tape_rt::gfx_blit` once per frame,
//! because framebuffer reads and scattered writes are slow), rectangles, lines, 8x16 text in the console font, and a PNG
//! writer for screenshots (`png`). `no_std`, no allocation: the caller owns the pixel slice.
#![cfg_attr(not(test), no_std)]

pub mod dial;
pub mod meter;
pub mod plot;
pub mod png;
pub mod scope;
pub mod theme;

mod font {
    // One source for the font: the kernel's console font, generated by tools/psf_to_rust.py.
    include!("../../../kernel/src/font_data.rs");
}

pub const GLYPH_WIDTH: u32 = font::FONT_WIDTH as u32;
pub const GLYPH_HEIGHT: u32 = font::FONT_HEIGHT as u32;

pub struct Canvas<'a> {
    pub pixels: &'a mut [u32],
    pub width: u32,
    pub height: u32,
}

impl<'a> Canvas<'a> {
    /// `pixels` must hold at least `width * height` entries; returns `None` otherwise.
    pub fn new(pixels: &'a mut [u32], width: u32, height: u32) -> Option<Self> {
        if pixels.len() < (width as usize) * (height as usize) {
            return None;
        }
        Some(Self { pixels, width, height })
    }

    pub fn clear(&mut self, rgb: u32) {
        let count = (self.width as usize) * (self.height as usize);
        self.pixels[..count].fill(rgb);
    }

    pub fn set(&mut self, x: i32, y: i32, rgb: u32) {
        if x >= 0 && y >= 0 && (x as u32) < self.width && (y as u32) < self.height {
            self.pixels[(y as usize) * (self.width as usize) + x as usize] = rgb;
        }
    }

    pub fn get(&self, x: u32, y: u32) -> u32 {
        if x < self.width && y < self.height { self.pixels[(y as usize) * (self.width as usize) + x as usize] } else { 0 }
    }

    /// Filled rectangle, clipped to the canvas.
    pub fn fill_rect(&mut self, x: i32, y: i32, w: u32, h: u32, rgb: u32) {
        let x0 = x.max(0) as i64;
        let y0 = y.max(0) as i64;
        let x1 = (x as i64 + w as i64).min(self.width as i64);
        let y1 = (y as i64 + h as i64).min(self.height as i64);
        if x0 >= x1 || y0 >= y1 {
            return;
        }
        for row in y0..y1 {
            let start = (row as usize) * (self.width as usize);
            self.pixels[start + x0 as usize..start + x1 as usize].fill(rgb);
        }
    }

    /// One-pixel rectangle outline.
    pub fn rect(&mut self, x: i32, y: i32, w: u32, h: u32, rgb: u32) {
        if w == 0 || h == 0 {
            return;
        }
        self.fill_rect(x, y, w, 1, rgb);
        self.fill_rect(x, y + h as i32 - 1, w, 1, rgb);
        self.fill_rect(x, y, 1, h, rgb);
        self.fill_rect(x + w as i32 - 1, y, 1, h, rgb);
    }

    /// Bresenham line, clipped per pixel.
    pub fn line(&mut self, x0: i32, y0: i32, x1: i32, y1: i32, rgb: u32) {
        let (mut x, mut y) = (x0, y0);
        let dx = (x1 - x0).abs();
        let dy = -(y1 - y0).abs();
        let sx = if x0 < x1 { 1 } else { -1 };
        let sy = if y0 < y1 { 1 } else { -1 };
        let mut err = dx + dy;
        loop {
            self.set(x, y, rgb);
            if x == x1 && y == y1 {
                break;
            }
            let doubled = 2 * err;
            if doubled >= dy {
                err += dy;
                x += sx;
            }
            if doubled <= dx {
                err += dx;
                y += sy;
            }
        }
    }

    /// One glyph (a Latin-9 byte); background pixels are left alone.
    pub fn glyph(&mut self, x: i32, y: i32, byte: u8, rgb: u32) {
        let rows = &font::FONT[byte as usize];
        for (row, bits) in rows.iter().enumerate() {
            for column in 0..GLYPH_WIDTH as i32 {
                if bits & (0x80 >> column) != 0 {
                    self.set(x + column, y + row as i32, rgb);
                }
            }
        }
    }

    /// Text in the console font, left edge at `x`; returns the x after the last glyph.
    pub fn text(&mut self, x: i32, y: i32, text: &str, rgb: u32) -> i32 {
        let mut at = x;
        for byte in text.bytes() {
            self.glyph(at, y, byte, rgb);
            at += GLYPH_WIDTH as i32;
        }
        at
    }

    /// Text in the console font enlarged `scale` times (each font pixel becomes a square), left edge at `x`; returns the
    /// x after the last glyph.
    pub fn text_scaled(&mut self, x: i32, y: i32, text: &str, scale: u32, rgb: u32) -> i32 {
        let scale = scale.max(1) as i32;
        let mut at = x;
        for byte in text.bytes() {
            for (row, bits) in font::FONT[byte as usize].iter().enumerate() {
                for column in 0..GLYPH_WIDTH as i32 {
                    if bits & (0x80 >> column) != 0 {
                        self.fill_rect(at + column * scale, y + row as i32 * scale, scale as u32, scale as u32, rgb);
                    }
                }
            }
            at += GLYPH_WIDTH as i32 * scale;
        }
        at
    }

    /// Text whose right edge is at `right`.
    pub fn text_right(&mut self, right: i32, y: i32, text: &str, rgb: u32) {
        self.text(right - text_width(text) as i32, y, text, rgb);
    }

    /// Text centred on `center`.
    pub fn text_centered(&mut self, center: i32, y: i32, text: &str, rgb: u32) {
        self.text(center - text_width(text) as i32 / 2, y, text, rgb);
    }
}

pub fn text_width(text: &str) -> u32 {
    text.len() as u32 * GLYPH_WIDTH
}

/// Formats `value` with `decimals` places into `out` (no allocation), returns the text. `out` should hold 16 bytes or more.
pub fn format_fixed(out: &mut [u8], value: f32, decimals: u32) -> &str {
    let mut len = 0;
    let mut put = |byte: u8, len: &mut usize| {
        if *len < out.len() {
            out[*len] = byte;
            *len += 1;
        }
    };
    let negative = value < 0.0;
    let mut scale = 1u32;
    for _ in 0..decimals {
        scale *= 10;
    }
    let scaled = ((if negative { -value } else { value }) * scale as f32 + 0.5) as u64;
    if negative && scaled != 0 {
        put(b'-', &mut len);
    }
    let whole = scaled / scale as u64;
    let fraction = scaled % scale as u64;
    let mut digits = [0u8; 20];
    let mut count = 0;
    let mut rest = whole;
    loop {
        digits[count] = b'0' + (rest % 10) as u8;
        count += 1;
        rest /= 10;
        if rest == 0 {
            break;
        }
    }
    while count > 0 {
        count -= 1;
        put(digits[count], &mut len);
    }
    if decimals > 0 {
        put(b'.', &mut len);
        let mut divisor = scale / 10;
        while divisor > 0 {
            put(b'0' + ((fraction / divisor as u64) % 10) as u8, &mut len);
            divisor /= 10;
        }
    }
    core::str::from_utf8(&out[..len]).unwrap_or("")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rect_is_clipped_not_wrapped() {
        let mut buffer = [0u32; 8 * 4];
        let mut canvas = Canvas::new(&mut buffer, 8, 4).unwrap();
        canvas.fill_rect(6, 2, 10, 10, 7);
        assert_eq!(canvas.get(7, 3), 7);
        assert_eq!(canvas.get(0, 3), 0, "no wrap onto the next row");
        canvas.fill_rect(-5, -5, 7, 7, 9);
        assert_eq!(canvas.get(1, 1), 9);
        assert_eq!(canvas.get(2, 1), 0);
    }

    #[test]
    fn line_reaches_both_ends_in_every_direction() {
        let mut buffer = [0u32; 16 * 16];
        let mut canvas = Canvas::new(&mut buffer, 16, 16).unwrap();
        for (a, b, c, d) in [(1, 1, 14, 9), (14, 9, 1, 1), (3, 12, 3, 2), (2, 5, 13, 5), (12, 2, 4, 13)] {
            canvas.clear(0);
            canvas.line(a, b, c, d, 1);
            assert_eq!(canvas.get(a as u32, b as u32), 1);
            assert_eq!(canvas.get(c as u32, d as u32), 1);
        }
    }

    #[test]
    fn text_draws_the_glyph_and_advances() {
        let mut buffer = [0u32; 32 * 16];
        let mut canvas = Canvas::new(&mut buffer, 32, 16).unwrap();
        let end = canvas.text(0, 0, "Hi", 5);
        assert_eq!(end, 16);
        assert!(canvas.pixels.iter().any(|&p| p == 5));
        assert!(canvas.pixels.iter().all(|&p| p == 0 || p == 5));
    }

    #[test]
    fn fixed_point_formatting() {
        let mut out = [0u8; 16];
        assert_eq!(format_fixed(&mut out, 12.345, 1), "12.3");
        assert_eq!(format_fixed(&mut out, -0.04, 1), "0.0");
        assert_eq!(format_fixed(&mut out, -3.5, 0), "-4");
        assert_eq!(format_fixed(&mut out, 1000.0, 0), "1000");
        assert_eq!(format_fixed(&mut out, 0.5, 2), "0.50");
    }
}
